parameters.jsCode:
const item = $input.first();
const analysis = JSON.parse(JSON.stringify(item.json.output));

if (
  !analysis ||
  !Array.isArray(analysis.findings) ||
  !analysis.chart ||
  typeof analysis.chart.ready !== 'boolean'
) {
  throw new Error('Analyst output has an invalid structure.');
}

const chart = analysis.chart;
const problems = [];

if (chart.ready) {
  if (analysis.comparison?.comparable !== true) {
    problems.push('The findings are not marked comparable.');
  }

  const labels = chart.labels;
  const values = chart.values;

  const arraysValid =
    Array.isArray(labels) &&
    Array.isArray(values) &&
    labels.length >= 2 &&
    labels.length === values.length;

  if (!arraysValid) {
    problems.push('Chart needs at least two matching labels and values.');
  } else {
    if (new Set(labels).size !== labels.length) {
      problems.push('Chart labels are duplicated.');
    }

    if (typeof chart.unit !== 'string' || !chart.unit.trim()) {
      problems.push('Chart unit is missing.');
    }

    for (let i = 0; i < labels.length; i++) {
      if (
        typeof labels[i] !== 'string' ||
        typeof values[i] !== 'number' ||
        !Number.isFinite(values[i])
      ) {
        problems.push(`Chart entry ${i + 1} has an invalid label or value.`);
        continue;
      }

      const matches = analysis.findings.filter(finding =>
        `${finding.subject} (${finding.year})` === labels[i] &&
        finding.value === values[i] &&
        finding.unit === chart.unit
      );

      if (matches.length !== 1) {
        problems.push(
          `Chart entry ${i + 1} does not uniquely match a finding with the same value and unit.`
        );
      }
    }
  }

  if (problems.length) {
    chart.ready = false;
    const explanation =
      'Chart omitted after validation: ' + problems.join(' ');

    chart.note = [chart.note, explanation].filter(Boolean).join(' ');
  }
}

if (!chart.ready) {
  chart.labels = [];
  chart.values = [];
}

const evidence = JSON.parse($('When Executed by Another Workflow').first().json.research_evidence);
if (analysis.question !== evidence.question || !Array.isArray(evidence.requirements) || !Array.isArray(evidence.accepted_passages)) throw new Error('Analyst lost the original evidence checklist.');
const rows = Array.isArray(analysis.coverage) ? analysis.coverage : [];
const checked = [];
analysis.missing_evidence = Array.isArray(analysis.missing_evidence) ? analysis.missing_evidence : [];
for (const requirement of evidence.requirements) {
  const row = rows.find(r => r.id === requirement.id);
  const directMatch = row?.status === 'supported' && evidence.accepted_passages.some(p =>
    p.relevance === 'direct' && p.url === row.source_url && p.quote === row.supporting_quote &&
    Array.isArray(p.requirement_ids) && p.requirement_ids.includes(requirement.id)
  );
  if (directMatch && typeof row.answer === 'string' && row.answer.trim()) checked.push({...row, description: requirement.description});
  else {
    checked.push({id:requirement.id,description:requirement.description,status:'missing',answer:'',source_url:'',supporting_quote:''});
    analysis.missing_evidence.push(`${requirement.id}: ${requirement.description}`);
  }
}
analysis.coverage = checked;
analysis.missing_evidence = [...new Set(analysis.missing_evidence)];
analysis.completeness = checked.every(r => r.status === 'supported') ? 'complete' : 'incomplete';


return [{
  json: {
    ...item.json,
    output: analysis
  }
}];

const analysis = JSON.parse(JSON.stringify(
  $('Validate Chart').first().json.output
));

analysis.chart.ready = false;
analysis.chart.labels = [];
analysis.chart.values = [];
analysis.chart.note = [
  analysis.chart.note,
  'Chart generation failed. The report is provided without a chart; the findings remain available.'
].filter(Boolean).join(' ');

return [{
  json: {
    analysis_result: JSON.stringify(analysis),
    chart_url: ''
  }
}];
